  LISTCAT ENTRIES(MY.VSAM.FILE) ALL
/*

//DELVSAM  JOB (ACCT),'DEL VSAM',CLASS=A,MSGCLASS=X
//STEP1    EXEC PGM=IDCAMS
//SYSPRINT DD SYSOUT=*
//SYSIN    DD *
  DELETE MY.VSAM.CLUSTER CLUSTER PURGE
/*

//VSAMDEL  JOB (ACCT),'VSAM DEL',CLASS=A,MSGCLASS=X
//DELETE   EXEC PGM=IDCAMS
//SYSPRINT DD SYSOUT=*
//SYSIN    DD *
  DELETE PROD.VSAM.KSDS CLUSTER PURGE
