/*

//RMVSAM   JOB (ACCT),'REMOVE VSAM',CLASS=A,MSGCLASS=X
//STEP1    EXEC PGM=IDCAMS
//SYSPRINT DD SYSOUT=*
//SYSIN    DD *
  DELETE USER.VSAM.DATA CLUSTER
  IF LASTCC = 8 THEN SET MAXCC = 0
/*

//DEFKSDS  JOB (ACCT),'DEF KSDS',CLASS=A,MSGCLASS=X
//STEP1    EXEC PGM=IDCAMS
//SYSPRINT DD SYSOUT=*
//SYSIN    DD *
  DEFINE CLUSTER (NAME(MY.VSAM.KSDS) -
    INDEXED -
    KEYS(8 0) -
    RECORDSIZE(100 100) -
    TRACKS(10 5)) -
  DATA (NAME(MY.VSAM.KSDS.DATA)) -
  INDEX (NAME(MY.VSAM.KSDS.INDEX))
/*

//DEFCLUST JOB (ACCT),'DEF CLUSTER',CLASS=A,MSGCLASS=X
//DEFINE   EXEC PGM=IDCAMS
//SYSPRINT DD SYSOUT=*
//SYSIN    DD *
