    INDEXED -
    KEYS(10 0) -
    RECORDSIZE(200 200) -
    CYLINDERS(5 2)) -
  DATA (NAME(PROD.MASTER.FILE.DATA)) -
  INDEX (NAME(PROD.MASTER.FILE.INDEX))
/*

//SORTJOB  JOB (ACCT),'SORT FILE',CLASS=A,MSGCLASS=X
//SORT     EXEC PGM=SORT
//SYSOUT   DD SYSOUT=*
//SORTIN   DD DSN=INPUT.FILE,DISP=SHR
//SORTOUT  DD DSN=OUTPUT.FILE,DISP=(NEW,CATLG,DELETE),
//            UNIT=SYSDA,SPACE=(TRK,(10,5))
//SYSIN    DD *
  SORT FIELDS=(1,10,CH,A)
/*

//SORTDATA JOB (ACCT),'SORT DATA',CLASS=A,MSGCLASS=X
//STEP1    EXEC PGM=SORT
//SYSOUT   DD SYSOUT=*
//SORTIN   DD DSN=MY.INPUT.FILE,DISP=SHR
//SORTOUT  DD DSN=MY.OUTPUT.FILE,DISP=(NEW,CATLG,DELETE),
//            UNIT=SYSDA,SPACE=(TRK,(10,5))
//SYSIN    DD *
  SORT FIELDS=(1,10,CH,A)
/*

//DOSORT   JOB (ACCT),'DOSORT',CLASS=A,MSGCLASS=X
//SORT     EXEC PGM=SORT
//SYSOUT   DD SYSOUT=*
//SORTIN   DD DSN=UNSORTED.DATA,DISP=SHR
//SORTOUT  DD DSN=SORTED.DATA,DISP=(NEW,CATLG,DELETE),
//            UNIT=SYSDA,SPACE=(CYL,(1,1))
//SYSIN    DD *
  SORT FIELDS=(1,20,CH,A)
/*

//MULTISRT JOB (ACCT),'MULTI SORT',CLASS=A,MSGCLASS=X
//STEP1    EXEC PGM=SORT
//SYSOUT   DD SYSOUT=*
